def lis_length(nums):
    if not nums:
        return 0

    # dp[i] represents the length of the longest increasing subsequence
    # ending at index i
    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
